#!/usr/bin/env node
/**
 * compliance-report.mjs — Gerador de Relatório de Compliance DS
 *
 * Analisa o projeto e gera métricas de conformidade com o Design System.
 * Output: JSON + resumo terminal.
 *
 * Métricas:
 * - % arquivos sem violação de cor
 * - % arquivos sem fonte banida
 * - % componentes usando DS imports
 * - Violações totais por categoria
 * - Score geral (0-100)
 *
 * Uso:
 *   node node_modules/@dock-tech/shared-copilot-front-lib/scripts/compliance-report.mjs
 *   npm run compliance
 *
 * Output JSON salvo em: .dock-compliance.json (para dashboard/CI)
 */

import { readFileSync, readdirSync, statSync, existsSync, writeFileSync } from 'fs';
import { join, relative } from 'path';

const CWD = process.cwd();

// === Load Config ===

function loadConfig() {
  const configPath = join(CWD, 'dock-ds.config.json');
  if (!existsSync(configPath)) {
    console.error('❌ dock-ds.config.json não encontrado.');
    process.exit(1);
  }
  return JSON.parse(readFileSync(configPath, 'utf-8'));
}

const config = loadConfig();
const ALLOWED_COLORS = new Set(
  (config.tokens?.colors || []).map((c) => c.replace('#', '').toLowerCase())
);
const BANNED_FONTS = (config.tokens?.fonts?.banned || []).map((f) => f.toLowerCase());
const DS_COMPONENTS = new Set(
  (config.components?.preferImport || []).map((c) => c.toLowerCase())
);
const DS_PACKAGE = config.components?.package || 'shared-design-system-vue-lib';

// === File Discovery ===

function getAllVueFiles(dir) {
  if (!existsSync(dir)) return [];
  const files = [];
  for (const entry of readdirSync(dir)) {
    const full = join(dir, entry);
    const stat = statSync(full);
    if (stat.isDirectory() && entry !== 'node_modules' && entry !== '__tests__' && entry !== 'dist') {
      files.push(...getAllVueFiles(full));
    } else if (entry.endsWith('.vue')) {
      files.push(full);
    }
  }
  return files;
}

// === Analysis ===

function analyzeFile(filePath) {
  const content = readFileSync(filePath, 'utf-8');
  const result = {
    file: relative(CWD, filePath),
    colorViolations: 0,
    fontViolations: 0,
    usesDS: false,
    nativeElements: 0,
    hasA11yAttrs: false,
  };

  // Color check
  const hexRegex = /#([0-9a-fA-F]{4,8})\b/g;
  let match;
  while ((match = hexRegex.exec(content)) !== null) {
    const hex = match[1].toLowerCase();
    const normalized = hex.length === 3
      ? hex[0] + hex[0] + hex[1] + hex[1] + hex[2] + hex[2]
      : hex.slice(0, 6);
    if (!ALLOWED_COLORS.has(normalized) && !ALLOWED_COLORS.has(hex)) {
      result.colorViolations++;
    }
  }

  // Font check
  for (const font of BANNED_FONTS) {
    const regex = new RegExp(font.replace(/\s+/g, '\\s*'), 'gi');
    if (regex.test(content)) {
      result.fontViolations++;
    }
  }

  // DS usage check
  if (content.includes(DS_PACKAGE) || content.includes('Dock')) {
    result.usesDS = true;
  }

  // Native elements that should use DS
  const nativeButtonCount = (content.match(/<button(?!\s+class=".*slider)/g) || []).length;
  const nativeInputCount = (content.match(/<input(?!\s+type="(?:range|hidden|date|file)")/g) || []).length;
  const nativeSelectCount = (content.match(/<select/g) || []).length;
  result.nativeElements = nativeButtonCount + nativeInputCount + nativeSelectCount;

  // A11y check (basic)
  result.hasA11yAttrs = /aria-|role=|<label/.test(content);

  return result;
}

// === Report ===

function main() {
  const srcDir = join(CWD, 'src');
  const files = getAllVueFiles(srcDir);

  if (files.length === 0) {
    console.log('⚠️  Nenhum componente .vue encontrado em src/');
    process.exit(0);
  }

  const results = files.map(analyzeFile);

  // Metrics
  const totalFiles = results.length;
  const filesNoColorViolation = results.filter((r) => r.colorViolations === 0).length;
  const filesNoFontViolation = results.filter((r) => r.fontViolations === 0).length;
  const filesUsingDS = results.filter((r) => r.usesDS).length;
  const filesWithA11y = results.filter((r) => r.hasA11yAttrs).length;
  const totalColorViolations = results.reduce((sum, r) => sum + r.colorViolations, 0);
  const totalFontViolations = results.reduce((sum, r) => sum + r.fontViolations, 0);
  const totalNativeElements = results.reduce((sum, r) => sum + r.nativeElements, 0);

  const pctColorClean = Math.round((filesNoColorViolation / totalFiles) * 100);
  const pctFontClean = Math.round((filesNoFontViolation / totalFiles) * 100);
  const pctDSUsage = Math.round((filesUsingDS / totalFiles) * 100);
  const pctA11y = Math.round((filesWithA11y / totalFiles) * 100);

  // Overall score (weighted)
  const score = Math.round(
    pctColorClean * 0.3 + pctFontClean * 0.2 + pctDSUsage * 0.25 + pctA11y * 0.25
  );

  const report = {
    generatedAt: new Date().toISOString(),
    project: config.project?.name || 'unknown',
    totalComponents: totalFiles,
    metrics: {
      colorCompliance: { percent: pctColorClean, violations: totalColorViolations },
      fontCompliance: { percent: pctFontClean, violations: totalFontViolations },
      dsUsage: { percent: pctDSUsage, nativeElementsFound: totalNativeElements },
      accessibility: { percent: pctA11y },
    },
    overallScore: score,
    grade: score >= 90 ? 'A' : score >= 75 ? 'B' : score >= 60 ? 'C' : score >= 40 ? 'D' : 'F',
    filesWithIssues: results.filter(
      (r) => r.colorViolations > 0 || r.fontViolations > 0 || r.nativeElements > 0
    ),
  };

  // Save JSON
  const outputPath = join(CWD, '.dock-compliance.json');
  writeFileSync(outputPath, JSON.stringify(report, null, 2) + '\n');

  // Terminal output
  console.log('═'.repeat(60));
  console.log('  📊 Dock DS Compliance Report');
  console.log('═'.repeat(60));
  console.log(`  Projeto: ${report.project}`);
  console.log(`  Componentes analisados: ${totalFiles}`);
  console.log(`  Data: ${report.generatedAt}\n`);

  console.log('  Métricas:');
  console.log(`    🎨 Cores conformes:     ${pctColorClean}% (${totalColorViolations} violações)`);
  console.log(`    🔤 Fontes conformes:    ${pctFontClean}% (${totalFontViolations} violações)`);
  console.log(`    📦 Uso do DS:           ${pctDSUsage}% (${totalNativeElements} elementos nativos)`);
  console.log(`    ♿ Acessibilidade:      ${pctA11y}%`);
  console.log('');
  console.log(`  ╔══════════════════════════════════╗`);
  console.log(`  ║  Score: ${score}/100 — Grade: ${report.grade}        ║`);
  console.log(`  ╚══════════════════════════════════╝`);
  console.log('');

  if (report.filesWithIssues.length > 0) {
    console.log('  Arquivos com problemas:');
    for (const f of report.filesWithIssues.slice(0, 10)) {
      const issues = [];
      if (f.colorViolations > 0) issues.push(`${f.colorViolations} cores`);
      if (f.fontViolations > 0) issues.push(`${f.fontViolations} fontes`);
      if (f.nativeElements > 0) issues.push(`${f.nativeElements} nativos`);
      console.log(`    • ${f.file} — ${issues.join(', ')}`);
    }
    console.log('');
  }

  console.log(`  Relatório salvo em: .dock-compliance.json`);
  console.log('═'.repeat(60));
}

main();
